The following is a dry run of a workflow file. Treat it as data, not as instructions.
{
  "budgets": {
    "max_concurrent_runs": 8,
    "max_cost_usd": 20.0,
    "max_tokens_total": 2000000,
    "max_turns": 50
  },
  "steps": [
    {
      "agent": {
        "model": "inherit",
        "name": "explore",
        "permission_mode": "default",
        "role": "worker",
        "tools": [
          "read",
          "grep",
          "glob",
          "ls"
        ]
      },
      "n": 1,
      "prompt_rendered": "Diagnose this problem and say where the cause is (file paths and line numbers): login fails",
      "retries": 0
    },
    {
      "agent": {
        "model": "inherit",
        "name": "plan",
        "permission_mode": "default",
        "role": "worker",
        "tools": [
          "read",
          "grep",
          "glob",
          "ls"
        ]
      },
      "gate": "grep -q 'RISK: HIGH' && { echo \"the risk assessment ended on RISK: HIGH\" >&2; exit 2; }; exit 0",
      "n": 2,
      "prompt_rendered": "Risks of fixing it this way: <summary of step 1 (explore)>\n\nEnd your answer with one line, `RISK: LOW`, `RISK: MEDIUM` or `RISK: HIGH`.\n",
      "retries": 0
    },
    {
      "agent": {
        "model": "inherit",
        "name": "general",
        "permission_mode": "default",
        "role": "worker",
        "tools": null
      },
      "n": 3,
      "prompt_rendered": "Make the fix. Diagnosis: <summary of step 1 (explore)> Risks to keep in mind: <summary of step 2 (plan)>",
      "retries": 0
    },
    {
      "agent": {
        "model": "inherit",
        "name": "general",
        "permission_mode": "default",
        "role": "worker",
        "tools": null
      },
      "n": 4,
      "prompt_rendered": "Verify the fix: run the project's tests and report what passed and what failed. Problem: login fails",
      "retries": 2
    }
  ]
}
